{
  "name": "opencode-blablador",
  "version": "0.1.6",
  "description": "Blablador (Helmholtz / JSC) provider plugin for OpenCode: measured context windows, live catalog, and reasoning effort mapping",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "blablador",
    "helmholtz",
    "jsc",
    "openai-compatible"
  ],
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "npm run build && node --test test/*.test.mjs",
    "test:live": "npm run build && node test/live.mjs",
    "prepublishOnly": "npm run typecheck && npm test"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.1.4"
  },
  "dependencies": {
    "blablador-core": "0.1.6"
  },
  "devDependencies": {
    "@opencode/plugin": "2.1.4",
    "@types/node": "^24.12.2",
    "typescript": "^7.0.2"
  }
}

import { Integration, Model, Plugin, Provider } from "@opencode/plugin";
import { BASE_URL, DEFAULT_RERANK_MODEL, EFFORT, FALLBACK_MODELS, TOKEN_ENV, VISION, displayName, familyOf, fetchLiveModels, outputCap, rerank, resolveToken, tokenize, variantsFor, webSearch, } from "./catalog.js";
const PACKAGE = "@opencode/ai/providers/openai-compatible";
const PROVIDER_ID = Provider.ID.make("blablador");
const INTEGRATION_ID = Integration.ID.make("blablador");
const FETCH_TIMEOUT_MS = 10_000;
const MISTRAL_NEUTRAL_ID = "alias-blablador-large";
const MISTRAL_GATEWAY_ID = "alias-mistral-large";
function gatewayModelId(id) {
    return id === MISTRAL_NEUTRAL_ID ? MISTRAL_GATEWAY_ID : id;
}
// Re-discovery TTL. A TUI outlives its startup conditions: the alias set moves, a failed fetch has to
// heal, and a token exported after launch has to start working. Matches pi's REFRESH_TTL_MS.
export const REFRESH_TTL_MS = 10 * 60 * 1000;
/** Order-insensitive identity of a catalog: what a republish would actually change. */
function catalogSignature(models) {
    return models
        .map((model) => `${model.id}|${model.root ?? ""}|${model.contextWindow}`)
        .sort()
        .join("\n");
}
function modelInfo(model) {
    const base = Model.Info.default(PROVIDER_ID, Model.ID.make(model.id));
    return {
        ...base,
        // Experiment: a neutral SDK id skips Mistral history rewrites; the wire keeps the real alias.
        ...(model.id === MISTRAL_GATEWAY_ID ? {
            modelID: Model.ID.make(MISTRAL_NEUTRAL_ID),
            body: { model: model.id },
        } : {}),
        // Root first: the aliases of one deployment (alias-large, alias-qwen3.8-flash-next) sort together.
        name: displayName(model, true),
        capabilities: {
            ...base.capabilities,
            input: VISION.has(model.id) ? ["text", "image"] : ["text"],
        },
        // outputCap keeps room for the prompt when a live window is smaller than the gateway ceiling.
        limit: { context: model.contextWindow, output: outputCap(model.contextWindow) },
        variants: variantsFor(model).map((variant) => ({
            id: Model.VariantID.make(variant.id),
            settings: { reasoningEffort: variant.reasoningEffort },
        })),
    };
}
export default Plugin.define({
    id: "opencode-blablador",
    async setup(ctx) {
        // Auth entry points: /connect stores a key, or the integration reads the env var directly.
        await ctx.integration.transform((integrations) => {
            integrations.update(INTEGRATION_ID, (integration) => {
                integration.name = "Blablador";
            });
            integrations.method.update({
                integrationID: INTEGRATION_ID,
                method: { type: "env", names: [TOKEN_ENV] },
            });
            integrations.method.update({
                integrationID: INTEGRATION_ID,
                method: { type: "key", label: "Blablador API token" },
            });
        });
        // The active catalog. The provider transform reads it on every rebuild, so a refresh plus
        // ctx.provider.reload() republishes models without a restart.
        const catalog = {
            models: FALLBACK_MODELS,
            roots: new Map(FALLBACK_MODELS.map((model) => [model.id, model.root])),
        };
        // Discovery must use the same credential the model resolver uses for inference: the active
        // connection first (a stored /connect key wins over the env var), env as the fallback.
        // resolveToken trims: a pasted key with surrounding whitespace is what the gateway 401s on.
        async function currentToken() {
            const connection = await ctx.integration.connection
                .active(INTEGRATION_ID)
                .catch(() => undefined);
            const credential = connection
                ? await ctx.integration.connection.resolve(connection).catch(() => undefined)
                : undefined;
            return resolveToken(credential, process.env[TOKEN_ENV]);
        }
        let lastError = "";
        async function discover() {
            const token = await currentToken();
            if (!token)
                return false;
            try {
                const models = await fetchLiveModels(token, AbortSignal.timeout(FETCH_TIMEOUT_MS));
                lastError = "";
                if (catalogSignature(models) === catalogSignature(catalog.models))
                    return false;
                catalog.models = models;
                catalog.roots = new Map(models.map((model) => [model.id, model.root]));
                return true;
            }
            catch (error) {
                const message = error instanceof Error ? error.message : String(error);
                // One line per distinct failure: an offline TUI would otherwise log the same error every tick.
                if (message !== lastError) {
                    lastError = message;
                    console.warn(`blablador: keeping the ${catalog.models.length}-model catalog; ${message}`);
                }
                return false;
            }
        }
        await discover();
        await ctx.provider.transform((providers) => {
            providers.add({
                info: {
                    ...Provider.Info.empty(PROVIDER_ID),
                    name: "Blablador",
                    activation: "auto",
                    package: PACKAGE,
                    settings: { baseURL: BASE_URL },
                    integrationID: INTEGRATION_ID,
                },
                models: catalog.models.map(modelInfo),
            });
        });
        // Blablador ships an anonymous SearXNG instance, so web search needs no extra key. Registered as
        // a first-class websearch provider (not a generic tool) so OpenCode's built-in websearch tool
        // uses it; the search logic is shared with pi-blablador through blablador-core. It becomes the
        // default only when none is configured: a user who picked another provider keeps it.
        await ctx.websearch.transform((editor) => {
            editor.add({
                id: "blablador",
                name: "Blablador (SearXNG)",
                execute: async ({ query }, { signal }) => (await webSearch(query, { signal })).map((result) => ({
                    url: result.url,
                    title: result.title,
                    content: result.content,
                    time: result.published === undefined ? {} : { published: result.published },
                })),
            });
            if (editor.default.get() === undefined)
                editor.default.set("blablador");
        });
        // count_tokens: check a text fits a model's window before processing it. The current model comes
        // from the session (the tool context only carries sessionID); the token from the active connection.
        await ctx.tool.transform((editor) => {
            editor.add({
                name: "count_tokens",
                description: "Count how many tokens a text uses against a Blablador model's context window. Use it to check a large input fits before processing it. By default it checks against the model's output cap; pass reserve (in tokens) to check against a specific output/thinking budget instead. Returns the token count and the model's max context length.",
                input: {
                    type: "object",
                    properties: {
                        text: { type: "string", description: "The text to count" },
                        model: { type: "string", description: "Blablador alias to check against (default: the current model)" },
                        reserve: {
                            type: "integer",
                            minimum: 0,
                            description: "Tokens to reserve for the model's output (replaces the default output cap when set)",
                        },
                    },
                    required: ["text"],
                },
                async execute(input, context) {
                    const { text, model, reserve } = input;
                    const token = await currentToken();
                    if (!token)
                        return { content: "No Blablador API token configured (set BLABLADOR_API_TOKEN)." };
                    const session = await ctx.session.get({ sessionID: context.sessionID }).catch(() => undefined);
                    const modelId = model ?? (session?.model?.providerID === "blablador"
                        ? gatewayModelId(session.model.id)
                        : undefined);
                    if (!modelId)
                        return { content: "No model to count against; pass a model." };
                    try {
                        const { count, maxModelLen } = await tokenize(modelId, text, token, context.signal);
                        // A prompt that fills the window still 400s once output is asked for; an explicit reserve
                        // replaces the default headroom — the caller asked for a specific output/thinking budget.
                        const headroom = maxModelLen != null ? (reserve ?? outputCap(maxModelLen)) : null;
                        const fits = count != null && maxModelLen != null && headroom != null ? count + headroom <= maxModelLen : null;
                        return {
                            content: `Counted ${count ?? "?"} tokens for "${modelId}" (max context ${maxModelLen ?? "?"}, reserving ${headroom ?? "?"}).${fits === false ? " Does NOT fit." : fits ? " Fits." : ""}`,
                            // metadata, not output: a Result.output requires a declared output schema, which this
                            // tool does not have (OpenCode rejects it with "declared output without an output schema").
                            metadata: { model: modelId, count, maxModelLen, reserve: headroom, fits },
                        };
                    }
                    catch (error) {
                        return { content: `Token count failed: ${error instanceof Error ? error.message : String(error)}` };
                    }
                },
            });
            // rerank: order the caller's own candidates with the gateway's reranker (shared call through
            // blablador-core). Rerankers are not chat models, so the session model is no default here.
            editor.add({
                name: "rerank",
                description: `Rank candidate passages or snippets by relevance to a query, using the gateway's reranker (default ${DEFAULT_RERANK_MODEL}). Use it when you already have candidate texts — web search results, file excerpts — and need them ordered by relevance before reading or quoting them. Returns the documents re-ordered best-first, each with a relevance score. No extra key needed.`,
                input: {
                    type: "object",
                    properties: {
                        query: { type: "string", description: "The question or topic to rank against" },
                        documents: {
                            type: "array",
                            items: { type: "string" },
                            description: "The candidate passages or snippets, in any order",
                        },
                        model: { type: "string", description: `Reranker alias to use (default: ${DEFAULT_RERANK_MODEL})` },
                    },
                    required: ["query", "documents"],
                },
                async execute(input, context) {
                    const { query, documents, model } = input;
                    const token = await currentToken();
                    if (!token)
                        return { content: "No Blablador API token configured (set BLABLADOR_API_TOKEN)." };
                    const modelId = model ?? DEFAULT_RERANK_MODEL;
                    try {
                        const { results } = await rerank(query, documents, token, model, context.signal);
                        // The model already holds the documents; what it needs is the order, so print them
                        // re-ordered best-first — taking the top N is then just taking the first N.
                        const ranked = [...results]
                            .sort((a, b) => b.score - a.score)
                            .map((result, position) => `${position + 1}. (score ${result.score})\n${documents[result.index]}`)
                            .join("\n\n");
                        return {
                            content: `Ranked ${results.length} documents for "${query}" (${modelId}), best first.\n\n${ranked}`,
                            // metadata, not output: a Result.output requires a declared output schema, which this
                            // tool does not have (OpenCode rejects it with "declared output without an output schema").
                            metadata: { model: modelId, results },
                        };
                    }
                    catch (error) {
                        return { content: `Rerank failed: ${error instanceof Error ? error.message : String(error)}` };
                    }
                },
            });
        });
        // V2 has no chat.params. These hooks build every request shape, so mapping here covers the
        // agent loop plus compaction, title generation, and synthetic requests.
        const sanitize = (event) => {
            const options = event.options;
            const requested = options.reasoningEffort ?? options.reasoning_effort;
            delete options.reasoningEffort;
            delete options.reasoning_effort;
            if (requested === undefined)
                return;
            const modelId = gatewayModelId(event.model.id);
            const rule = EFFORT[familyOf(modelId, catalog.roots.get(modelId) ?? null)];
            if (!rule)
                return;
            const mapped = typeof requested === "string" ? rule[requested] : undefined;
            options.reasoningEffort = mapped ?? "low";
        };
        // A stored key with stray whitespace 401s every chat even when discovery is fine, because
        // inference auth is OpenCode's own. Trim it on the wire: the clean-key path only reads a
        // header, and the value is rewritten only when trimming actually changes it.
        const trimAuth = (event) => {
            const value = event.request.headers.get("authorization");
            if (!value)
                return;
            const bearer = /^Bearer (.*)$/.exec(value);
            const raw = bearer?.[1];
            if (raw === undefined)
                return;
            const token = raw.trim();
            if (token === raw)
                return;
            event.request.headers.set("authorization", `Bearer ${token}`);
        };
        const registrations = await Promise.all([
            ctx.session.hook("context", sanitize, { providerID: PROVIDER_ID }),
            ctx.session.hook("compaction", sanitize, { providerID: PROVIDER_ID }),
            ctx.session.hook("generate", sanitize, { providerID: PROVIDER_ID }),
            ctx.session.hook("title", sanitize, { providerID: PROVIDER_ID }),
            ctx.session.hook("http.request", trimAuth, { providerID: PROVIDER_ID }),
        ]);
        // /connect or a credential switch changes the key and the reachable aliases, and the alias set
        // moves under a long-running TUI anyway: re-discover on either and reload only if the catalog
        // actually moved. Switched is what `credential create` emits when a new key becomes active; a
        // bad key just keeps the last good catalog with a warning.
        const watch = new AbortController();
        let refreshing = false;
        async function refreshCatalog() {
            if (refreshing)
                return;
            refreshing = true;
            try {
                if (await discover())
                    await ctx.provider.reload();
            }
            catch (error) {
                console.warn("blablador: catalog refresh failed", error);
            }
            finally {
                refreshing = false;
            }
        }
        void (async () => {
            try {
                for await (const event of ctx.event.subscribe({ signal: watch.signal })) {
                    if (event.type !== "credential.switched")
                        continue;
                    if (event.data.integrationID !== INTEGRATION_ID)
                        continue;
                    await refreshCatalog();
                }
            }
            catch (error) {
                if (!watch.signal.aborted)
                    console.warn("blablador: credential watch stopped", error);
            }
        })();
        // unref: a pending refresh must not hold the process open, or a one-shot CLI command hangs for
        // ten minutes after it has printed its models.
        const refresh = setInterval(() => void refreshCatalog(), REFRESH_TTL_MS);
        refresh.unref?.();
        return async () => {
            clearInterval(refresh);
            watch.abort();
            await Promise.all(registrations.map((registration) => registration.dispose()));
        };
    },
});
